import React, { useState, useEffect } from 'react';
import './wea.css';
import { WiDaySunny, WiCloudy, WiRain, WiStrongWind, WiHumidity, WiBarometer } from 'react-icons/wi';

export default function weather() {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [activeTab, setActiveTab] = useState('WEATHER');

  // تحديث الوقت كل دقيقة
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  // تنسيق الوقت
  const formatTime = (date) => {
    return date.toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: true
    }).toUpperCase();
  };

  // تنسيق التاريخ
  const formatDate = (date) => {
    const days = ['SUNDAY', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY'];
    const months = ['JANUARY', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE', 'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'];
    
    const dayName = days[date.getDay()];
    const day = date.getDate();
    const month = months[date.getMonth()];
    
    // إضافة اللاحقة المناسبة للرقم
    const getOrdinal = (n) => {
      if (n > 3 && n < 21) return 'th';
      switch (n % 10) {
        case 1: return 'st';
        case 2: return 'nd';
        case 3: return 'rd';
        default: return 'th';
      }
    };
    
    return `${dayName} ${day}${getOrdinal(day)} ${month}`;
  };

  // بيانات الطقس لوجدة
  const weatherData = {
    current: {
      temp: 82,
      condition: "Sunny",
      icon: "☀️",
      humidity: 65,
      wind: 12,
      pressure: 1013,
      feelsLike: 84
    },
    weeklyForecast: [
      { day: "MON", date: 27, temp: 82, icon: "☀️", condition: "Sunny" },
      { day: "TUE", date: 28, temp: 79, icon: "⛅", condition: "Partly Cloudy" },
      { day: "WED", date: 29, temp: 72, icon: "🌤️", condition: "Mostly Sunny" },
      { day: "THU", date: 30, temp: 65, icon: "☁️", condition: "Cloudy" },
      { day: "FRI", date: 31, temp: 63, icon: "🌧️", condition: "Rainy" },
      { day: "SAT", date: 1, temp: 68, icon: "⛈️", condition: "Stormy" },
      { day: "SUN", date: 2, temp: 69, icon: "🌦️", condition: "Showers" }
    ],
    locations: [
      { name: "OUJDA, MA", time: "20:12 PM", temp: 82, condition: "Sunny" }
    ]
  };

  return (
    <div className="app">
      {/* Header Section */}
      <header className="header">
        <div className="location-info">
          <div className="address">
            <div className="street">Angle Rue Sidi Brahim & Rue Abi Chouaib Doukkali</div>
            <div className="city-country">OUJDA, MOROCCO</div>
          </div>
          <div className="time-display">
            <div className="time">{formatTime(currentTime)}</div>
            <div className="date">{formatDate(currentTime)}</div>
          </div>
        </div>
      </header>

      {/* Navigation Tabs */}
      <nav className="navigation">
        <div className="nav-tabs">
          <button 
            className={`nav-tab ${activeTab === 'WEATHER' ? 'active' : ''}`}
            onClick={() => setActiveTab('WEATHER')}
          >
            WEATHER
          </button>
          <button 
            className={`nav-tab ${activeTab === 'NEWS' ? 'active' : ''}`}
            onClick={() => setActiveTab('NEWS')}
          >
            NEWS & EVENTS
          </button>
          <button 
            className={`nav-tab ${activeTab === 'GALLERY' ? 'active' : ''}`}
            onClick={() => setActiveTab('GALLERY')}
          >
            GALLERY (30)
          </button>
        </div>
      </nav>

      <main className="main-content">
        {/* Current Weather Section */}
        <div className="weather-section">
          <div className="current-weather">
            <div className="temp-display">
              <div className="temp-large">{weatherData.current.temp}°</div>
              <div className="temp-details">
                <div className="condition">{weatherData.current.condition}</div>
                <div className="feels-like">Feels like {weatherData.current.feelsLike}°</div>
              </div>
            </div>
            
            <div className="weather-stats">
              <div className="stat-item">
                <WiHumidity className="stat-icon" />
                <div className="stat-info">
                  <div className="stat-value">{weatherData.current.humidity}%</div>
                  <div className="stat-label">HUMIDITY</div>
                </div>
              </div>
              
              <div className="stat-item">
                <WiStrongWind className="stat-icon" />
                <div className="stat-info">
                  <div className="stat-value">{weatherData.current.wind} mph</div>
                  <div className="stat-label">WIND</div>
                </div>
              </div>
              
              <div className="stat-item">
                <WiBarometer className="stat-icon" />
                <div className="stat-info">
                  <div className="stat-value">{weatherData.current.pressure}</div>
                  <div className="stat-label">PRESSURE</div>
                </div>
              </div>
            </div>
          </div>

          {/* Weekly Forecast */}
          <div className="weekly-forecast">
            <div className="section-header">
              <h3>WEEKLY FORECAST</h3>
              <div className="location-count">1/1</div>
            </div>
            
            <div className="forecast-grid">
              {weatherData.weeklyForecast.map((day, index) => (
                <div className="forecast-day" key={index}>
                  <div className="day-info">
                    <div className="day-name">{day.day}</div>
                    <div className="day-date">{day.date}</div>
                  </div>
                  <div className="day-weather">
                    <div className="day-icon">{day.icon}</div>
                    <div className="day-temp">{day.temp}°</div>
                  </div>
                  <div className="day-condition">{day.condition}</div>
                </div>
              ))}
            </div>
          </div>

          {/* Latest Locations */}
          <div className="latest-locations">
            <div className="section-header">
              <h3>LATEST LOCATIONS</h3>
              <div className="location-count">1/1</div>
            </div>
            
            <div className="locations-list">
              {weatherData.locations.map((location, index) => (
                <div className="location-card" key={index}>
                  <div className="location-header">
                    <div className="loc-name">{location.name}</div>
                    <div className="loc-time">{location.time}</div>
                  </div>
                  <div className="location-weather">
                    <div className="loc-temp">{location.temp}°</div>
                    <div className="loc-condition">{location.condition}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Additional Info Section */}
        <div className="additional-info">
          <div className="info-card purple-bg">
            <h4>OUJDA INFO</h4>
            <ul className="info-list">
              <li>• Coordinates: 34.6810° N, 1.9086° W</li>
              <li>• Elevation: 470m</li>
              <li>• Population: 494,252</li>
              <li>• Time Zone: GMT+1</li>
            </ul>
          </div>
          
          <div className="info-card">
            <h4>TODAY'S HIGHLIGHTS</h4>
            <div className="highlight">
              <div className="highlight-icon">🌅</div>
              <div className="highlight-info">
                <div className="highlight-title">SUNRISE</div>
                <div className="highlight-value">06:15 AM</div>
              </div>
            </div>
            <div className="highlight">
              <div className="highlight-icon">🌇</div>
              <div className="highlight-info">
                <div className="highlight-title">SUNSET</div>
                <div className="highlight-value">08:10 PM</div>
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="footer">
        <div className="footer-content">
          <div className="footer-left">
            <div className="app-name">OUJDA WEATHER</div>
            <div className="app-version">v1.0 • Purple Theme</div>
          </div>
          <div className="footer-right">
            <div className="update-time">Last update: {formatTime(currentTime)}</div>
            <div className="data-source">Weather Data: Mock API</div>
          </div>
        </div>
      </footer>
    </div>
  );
}
